// ghostty: файл конфигурации с цветами. Подключается из dotfiles через
// config-file = ?~/.local/share/uiu/ghostty/uiu.conf

import type { Theme } from "../theme";

const ANSI = [
  "black", "red", "green", "yellow", "blue", "magenta", "cyan", "white",
] as const;

export function ghostty(t: Theme): string {
  const r = (name: string) => t.role(name).hex;
  const lines = [
    "# uiu — ghostty colors (light)",
    "# generated by packages/theme-gen from theme/*.css — do not edit by hand",
    "",
    `background = ${r("surface-base")}`,
    `foreground = ${r("text")}`,
    `cursor-color = ${r("text")}`,
    `cursor-text = ${r("surface-base")}`,
    `selection-background = ${r("accent-selection")}`,
    `selection-foreground = ${r("text")}`,
    `search-background = ${r("accent-search")}`,
    `search-foreground = ${r("text")}`,
    `search-selected-background = ${r("accent-search-current")}`,
    `search-selected-foreground = ${r("text-on-accent")}`,
    `split-divider-color = ${r("border-subtle")}`,
    "",
    ...ANSI.map((n, i) => `palette = ${i}=${r(`ansi-${n}`)}`),
    ...ANSI.map((n, i) => `palette = ${i + 8}=${r(`ansi-bright-${n}`)}`),
    "",
  ];
  return lines.join("\n");
}
